+__aicore__ inline constexpr GmFormat GetQueryGmFormat() {
+    if constexpr (LAYOUT == LayOutTypeEnum::LAYOUT_BSH) {
+        return GmFormat::BSNGD;
+    } else if constexpr (LAYOUT == LayOutTypeEnum::LAYOUT_SBH) {
+        return GmFormat::SBNGD;
