+FABlockCubeMlaFullquant<TEMPLATE_ARGS>::GetKeyGm(RunInfo<isInfer> &runInfo, 
+    ConstInfo<isInfer, hasRope> &constInfo)
+{
+    if constexpr (isInfer) {
+        GlobalTensor<INPUT_T> tempKeyGm = this->keyGm.gmTensor;
