+    if (constInfo.isSoftmaxLseEnable) {
+        // 8: 适配TND, 每行结果存为8个重复lse元素(32B对齐)
+        this->tPipe->InitBuffer(softmaxLseQueue, 1, (BaseClass::s1BaseSize >> 1U) * sizeof(float) * 8);
