+__aicore__ inline void FABlockVecInferMlaFullquant<TEMPLATE_ARGS>::InitUniqueLocalBuffer(ConstInfo<isInfer, hasRope> &constInfo)
+{
+    if (constInfo.isSoftmaxLseEnable) {
+        // 8: 适配TND，每行的结果存为8个重复lse元素（32B对齐）
