+            OP_LOGE(fiaInfo.opName,
+                "When page attention enable and input layout is %s, PA BnNBsD is not supported.", inputLayout.c_str()),
+            return ge::GRAPH_FAILED);
+    }
+    return ge::GRAPH_SUCCESS;
+}
