+ge::graphStatus PostQuantChecker::CheckParaExistence(const FiaTilingInfo &fiaInfo)
+{
+    OP_LOGI(fiaInfo.opName, "Begin PostQuantChecker::CheckParaExistence!");
+    if (ge::GRAPH_SUCCESS != CheckExistenceQuantScale2(fiaInfo)) {
